package com.booksyde.controller; import com.booksyde.dto.request.SaveReadingProgressRequest; import com.booksyde.dto.response.ReadingProgressResponse; import com.booksyde.service.ReadingProgressService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/reading-progress") public class ReadingProgressController {private final ReadingProgressService s; public ReadingProgressController(ReadingProgressService s){this.s=s;} @GetMapping("/{volumeId}") public ReadingProgressResponse get(@AuthenticationPrincipal Jwt j,@PathVariable UUID volumeId){return s.get(j,volumeId);} @PutMapping("/{volumeId}") public ReadingProgressResponse save(@AuthenticationPrincipal Jwt j,@PathVariable UUID volumeId,@Valid @RequestBody SaveReadingProgressRequest r){return s.save(j,volumeId,r);}}